2244	    void choose_header_item(const wxString& name, std::function<void()> then)
2245	    {
2246	        auto* menu = visible_header_menu();
2247	        auto* item = menu ? wxWindow::FindWindowByName(name,menu) : nullptr;
2248	        if (!item || !item->IsEnabled()) throw std::runtime_error("missing enabled header menu item: " + name.ToStdString());
2249	        for (size_t i=0;i<menu->GetChildren().size() && menu->selected_item() != item;++i) {
2250	            wxKeyEvent down(wxEVT_CHAR); down.m_keyCode = WXK_DOWN;
2251	            menu->GetEventHandler()->ProcessEvent(down);
2252	        }
2253	        check(menu->selected_item() == item,"header_menu_keyboard_selects_enabled_row");
2254	        wxKeyEvent enter(wxEVT_CHAR); enter.m_keyCode = WXK_RETURN;
2255	        menu->GetEventHandler()->ProcessEvent(enter);
2256	        then();
2257	    }
2258	
2259	    // A mouse-opened menu must start with nothing highlighted, matching native
2260	    // menus; a keyboard-opened one must start on the first enabled row so a
2261	    // keyboard user has somewhere to arrow from. Keyboard runs first so the
2262	    // mouse case proves a click clears the flag rather than reading its default.
2263	    void verify_header_menu_open_paths(HeaderButton* chevron)
2264	    {
2265	        if (!chevron) return;
2266	        auto has_enabled_item = [](HeaderMenu* menu) {
2267	            if (!menu) return false;
2268	            for (auto* child : menu->GetChildren())
2269	                if (auto* item = dynamic_cast<HeaderButton*>(child); item && item->IsEnabled()) return true;
2270	            return false;
2271	        };
2272	        auto dismiss = [](HeaderMenu* menu) {
2273	            if (!menu) return;
2274	            wxKeyEvent escape(wxEVT_CHAR_HOOK); escape.m_keyCode = WXK_ESCAPE;
2275	            menu->GetEventHandler()->ProcessEvent(escape);
2276	        };
2277	        wxKeyEvent open_key(wxEVT_KEY_DOWN); open_key.m_keyCode = WXK_RETURN;
2278	        chevron->ProcessWindowEvent(open_key);
2279	        auto* key_menu = visible_header_menu();
2280	        check(key_menu && bool(key_menu->selected_item()) == has_enabled_item(key_menu),
2281	              "header_keyboard_menu_selects_an_enabled_row_when_available");
2282	        dismiss(key_menu);
2283	
2284	        wxMouseEvent press(wxEVT_LEFT_DOWN), release(wxEVT_LEFT_UP);
2285	        chevron->ProcessWindowEvent(press);
2286	        chevron->ProcessWindowEvent(release);
2287	        auto* mouse_menu = visible_header_menu();
2288	        check(mouse_menu && !mouse_menu->selected_item(),"header_mouse_menu_starts_unhighlighted");
2289	        if (mouse_menu) {
2290	            wxKeyEvent down(wxEVT_CHAR); down.m_keyCode = WXK_DOWN;
2291	            mouse_menu->GetEventHandler()->ProcessEvent(down);
2292	            check(bool(mouse_menu->selected_item()) == has_enabled_item(mouse_menu),
2293	                  "header_mouse_menu_arrow_selects_an_enabled_row_when_available");
2294	        }
2295	        dismiss(mouse_menu);
2296	    }
