2339	    // Clicks a menu row the way the platform's own pointer reaches it.
2340	    //
2341	    // Orca's PopupWindow installs a mouse re-dispatcher under __WXOSX__ only
2342	    // (Widgets/PopupWindow.hpp): there the popup receives the event and
2343	    // forwards it to the child under the pointer, so posting to the popup is
2344	    // what a real click does. Windows delivers to the child window directly
2345	    // and nothing forwards, so a click posted to the popup arrives nowhere and
2346	    // the row is never invoked -- the menu simply stays as it was, which reads
2347	    // as "the row did nothing" rather than as a broken click.
2348	    void click_row(HeaderMenu* menu, wxWindow* row)
2349	    {
2350	#ifdef __WXOSX__
2351	        wxWindow* target = menu;
2352	        const wxPoint at = row->GetPosition() + wxPoint(row->GetSize().x / 2, row->GetSize().y / 2);
2353	#else
2354	        wxWindow* target = row;
2355	        const wxPoint at(row->GetSize().x / 2, row->GetSize().y / 2);
2356	#endif
2357	        for (auto type : {wxEVT_LEFT_DOWN, wxEVT_LEFT_UP}) {
2358	            wxMouseEvent mouse(type);
2359	            mouse.SetPosition(at);
2360	            mouse.SetEventObject(target);
2361	            target->GetEventHandler()->ProcessEvent(mouse);
2362	        }
2363	    }
2364	
2365	    // Clicks a keeps_open row and lets the deferred rebuild run. Returns the
2366	    // menu that replaced it.
2367	    HeaderMenu* click_menu_row(HeaderMenu* menu, const wxString& name)
2368	    {
2369	        auto* row = dynamic_cast<HeaderButton*>(wxWindow::FindWindowByName(name, menu));
2370	        if (row == nullptr || !row->IsEnabled()) return nullptr;
2371	        click_row(menu, row);
2372	        wxYield();
2373	        return visible_header_menu();
2374	    }
2375	
2376	    // The selectable rows of an open menu, in order. Rows are named by their
2377	    // full label, which the paint-time ellipsis never shortens.
2378	    std::vector<std::string> menu_row_names(HeaderMenu* menu) const
2379	    {
2380	        std::vector<std::string> names;
2381	        for (auto* child : menu->GetChildren())
2382	            if (auto* button = dynamic_cast<HeaderButton*>(child)) names.push_back(ui_text(button->GetName()));
2383	        return names;
2384	    }
2385	
2386	    // "Generic preset…" must narrow the list by the vendor the profile
2387	    // declares. The earlier implementation instead typed "Generic" into the
2388	    // search box and re-ran the substring search, which matched any preset
2389	    // whose name happened to read "generic", missed generic presets named
2390	    // otherwise, and left a word in a field the person never typed into. Each
2391	    // of those three is checked here, so a regression to text matching fails
2392	    // rather than passing on a list that happens to look similar.
2393	    void verify_generic_preset_filter()
2394	    {
2395	        installed_shell()->status_row()->open_spool_menu();
2396	        auto* menu = visible_header_menu();
2397	        check(menu != nullptr, "spool_menu_opens_for_the_generic_filter");
2398	        if (menu == nullptr) return;
2399	
2400	        menu = click_menu_row(menu, ui_name("Other spool…"));
2401	        check(menu != nullptr, "other_spool_step_opens");
2402	        if (menu == nullptr) return;
2403	        const std::size_t unfiltered_rows = menu_row_names(menu).size();
2404	
2405	        menu = click_menu_row(menu, ui_name("Generic preset…"));
2406	        check(menu != nullptr, "generic_preset_step_opens");
2407	        if (menu == nullptr) return;
2408	
2409	        wxTextCtrl* field = nullptr;
2410	        for (auto* child : menu->GetChildren())
2411	            if (auto* text = dynamic_cast<wxTextCtrl*>(child); text && field == nullptr) field = text;
2412	        check(field != nullptr && field->GetValue().empty(), "generic_step_leaves_the_search_field_empty");
2413	
2414	        const std::vector<std::string> names = menu_row_names(menu);
2415	        check(!names.empty() && names.front().find("GENERIC") != std::string::npos,
2416	              "generic_step_title_says_the_list_is_filtered");
2417	        check(names.size() < unfiltered_rows, "generic_step_shortens_the_list");
2418	
2419	        // The listed rows must be exactly the compatible presets whose vendor
2420	        // is Generic -- no branded preset admitted, no generic one dropped.
2421	        std::vector<std::string> listed, expected;
2422	        for (std::size_t i = 1; i < names.size(); ++i)
2423	            if (names[i] != "Import a preset file…") listed.push_back(names[i]);
2424	        std::string branded; // an alias the vendor test must have excluded
2425	        for (const auto& filament : SetupCommands::compatible_filaments()) {
2426	            if (filament.vendor == SetupCommands::kGenericVendor) expected.push_back(ui_text(filament.alias));
2427	            else if (branded.empty()) branded = ui_text(filament.alias);
2428	        }
2429	        std::sort(listed.begin(), listed.end());
2430	        std::sort(expected.begin(), expected.end());
2431	        check(!expected.empty(), "the_printer_has_generic_filament_presets");
2432	        check(listed == expected, "generic_step_lists_exactly_the_generic_vendor_presets");
2433	        check(!branded.empty() && std::find(listed.begin(), listed.end(), branded) == listed.end(),
2434	              "generic_step_drops_a_branded_preset");
2435	
2436	        // Back must reach the full list again, not leave the menu.
2437	        menu = click_menu_row(menu, ui_name(names.front()));
2438	        check(menu != nullptr && menu_row_names(menu).size() == unfiltered_rows,
2439	              "generic_step_returns_to_the_full_list");
2440	        if (menu == nullptr) return;
2441	        menu->close();
2442	        wxYield();
2443	        check(!chip_half_open(), "generic_step_dismisses_cleanly");
2444	    }
