2446	    void verify_header_setup(Preset::Type type)
2447	    {
2448	        // The printer half opens the printer menu; the spool half's row menu
2449	        // is where Filament settings… now lives, one step in from the list.
2450	        if (type == Preset::TYPE_PRINTER) {
2451	            // Printer settings… talks about the selected printer in the
2452	            // printer conversation on Home. Only a printer saved under a name
2453	            // can be changed there, so one is saved from the fixture's own
2454	            // profile and selected for the length of the check.
2455	            m_header_setup_restore_printer = wxGetApp().preset_bundle->printers.get_selected_preset_name();
2456	            m_header_setup_printer         = Printers::add_named_printer(*m_plater, "Header Printer", {});
2457	            check(SetupCommands::current_printer().nickname.ToStdString() == m_header_setup_printer,
2458	                  "header_setup_named_printer_selected");
2459	            installed_shell()->status_row()->open_printer_menu();
2460	            choose_header_item(ui_name("Printer settings…"),
2461	                [self=shared_from_this()] { self->verify_header_printer_settings_open(); });
2462	            return;
2463	        }
2464	        installed_shell()->status_row()->open_spool_menu();
2465	        // Row one of the spool list is the current spool; its ⋯ menu carries
2466	        // the filament editor.
2467	        auto* menu = visible_header_menu();
2468	        check(menu != nullptr, "spool_menu_opens");
2469	        if (menu == nullptr) return;
2470	        auto* row = first_spool_row(menu);
2471	        check(row != nullptr, "spool_menu_lists_a_spool");
2472	        if (row == nullptr) return;
2473	        row->invoke_row_action();
2474	        m_frame->CallAfter([self=shared_from_this(),type] {
2475	            self->choose_header_item(ui_name("Filament settings…"),
2476	                [self,type] { self->verify_header_setup_open(type); });
2477	        });
2478	    }
2479	
2480	    // The first selectable row of an open spool menu: the most recently used
2481	    // remembered spool.
2482	    HeaderButton* first_spool_row(HeaderMenu* menu) const
2483	    {
2484	        for (auto* child : menu->GetChildren())
2485	            if (auto* button = dynamic_cast<HeaderButton*>(child); button && button->has_row_action())
2486	                return button;
2487	        return nullptr;
2488	    }
2489	
2490	    // Drives the two-click swap without a pointer: open the half, pick a row
2491	    // that is not the current spool, and confirm the chip followed.
2492	    // Writes the chip as it actually renders, in both appearance modes and in
2493	    // the long-name case, so appearance is evidence rather than a claim. The
2494	    // application draws these itself, so they need no screen-capture
2495	    // permission and do not depend on what else is on the tester's display.
2496	    void capture_chip_appearance()
2497	    {
2498	        auto* row  = installed_shell()->status_row();
2499	        auto* chip = dynamic_cast<PrinterSpoolChip*>(wxWindow::FindWindowByName("Printer and spool", row));
2500	        check(chip != nullptr, "chip_is_in_the_header");
2501	        if (chip == nullptr) return;
2502	
2503	        // The automated run's data directory is temporary and removed at exit.
2504	        // JUSPRIN_ARTIFACT_DIR keeps the images for a human to look at.
2505	        const char* artifact_dir = std::getenv("JUSPRIN_ARTIFACT_DIR");
2506	        const fs::path out = artifact_dir != nullptr ? fs::path(artifact_dir)
2507	                                                     : fs::path(data_dir()) / "chip-appearance";
2508	        fs::create_directories(out);
2509	        const bool was_dark = wxGetApp().dark_mode();

