102	// yet". Both are drawn at the same size so rows stay aligned either way.
103	void draw_dot(wxGraphicsContext& gc, const std::optional<wxColour>& dot, double x, double y, double size,
104	              const ShellPalette& p)
105	{
106	    if (!dot) return;
107	    if (dot->IsOk()) {
108	        // A quiet ring keeps a white or near-background spool visible.
109	        gc.SetPen(wxPen(p.border_subtle));
110	        gc.SetBrush(wxBrush(*dot));
111	    } else {
112	        wxPen dashed(p.text_secondary, 1, wxPENSTYLE_SHORT_DASH);
113	        gc.SetPen(dashed);
114	        gc.SetBrush(*wxTRANSPARENT_BRUSH);
115	    }
116	    gc.DrawEllipse(x, y, size, size);
117	}
