// The header setup steps changed the printer and filament presets since
// the plate was sliced. Orca applies a config change to the print from a
// 500 ms one-shot timer (schedule_background_process), so until it fires
// the stale slice still reads as valid and Print is offered; once it
// fires, the slice is invalid and Print is not. Apply the pending change
// now, through Orca's own update, then slice again if that invalidated the
// plate, so the preflight runs on a Print the header really offers.
void offer_print_for_current_settings(std::function<void()> then)
{
    m_plater->update(false, true);
    installed_shell()->status_row()->request_slice();
    wait_until([] {
        auto* row = installed_shell()->status_row();
        const auto state = row->action_state();
        const auto actions = primary_print_action(state);
        return !state.slicing && actions.primary.action == PrintAction::Print && actions.primary.enabled;
    }, "print_offered_for_current_settings", std::move(then));
}

